394: .filter-row output{font-family:var(--mono);font-size:7px;color:#8a8882;text-align:right;font-variant-numeric:tabular-nums;letter-spacing:.02em}
395: input[type=range]{
396:   -webkit-appearance:none;appearance:none;width:100%;height:16px;background:transparent;outline:none;margin:0;cursor:pointer;
397: }
398: input[type=range]::-webkit-slider-runnable-track{height:2px;border-radius:5px;background:linear-gradient(90deg,var(--acid) 0%,var(--acid) var(--pct,50%),rgba(255,255,255,.12) var(--pct,50%))}
399: input[type=range]::-moz-range-track{height:2px;border-radius:5px;background:rgba(255,255,255,.12)}
400: input[type=range]::-moz-range-progress{height:2px;border-radius:5px;background:var(--acid)}
401: input[type=range]::-webkit-slider-thumb{
402:   -webkit-appearance:none;width:10px;height:10px;border-radius:50%;background:#f2f0e9;margin-top:-4px;
403:   box-shadow:0 0 0 2px #141416,0 0 0 3px rgba(255,255,255,.2);transition:transform .15s,box-shadow .15s;
404: }
405: input[type=range]::-webkit-slider-thumb:hover{transform:scale(1.18);box-shadow:0 0 0 2px #141416,0 0 0 3px var(--acid)}
406: input[type=range]::-moz-range-thumb{width:10px;height:10px;border:0;border-radius:50%;background:#f2f0e9;box-shadow:0 0 0 2px #141416,0 0 0 3px rgba(255,255,255,.2)}
407: input[type=range].active::-webkit-slider-thumb{background:var(--acid);box-shadow:0 0 0 2px #141416,0 0 0 3px rgba(217,255,98,.5)}
