409: .ratio-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}
410: .ratio-btn{
411:   border:1px solid var(--line);background:rgba(255,255,255,.018);border-radius:8px;padding:9px 4px 7px;
412:   display:flex;flex-direction:column;align-items:center;gap:5px;color:#8d8b84;transition:.18s;
