432: .switch-track{width:100%;height:100%;border-radius:100px;background:#29292e;border:1px solid rgba(255,255,255,.09);transition:.2s;position:relative}
433: .switch-track::after{content:"";position:absolute;width:11px;height:11px;border-radius:50%;background:#8b8983;top:2px;left:2px;transition:.2s}
434: .switch input:checked + .switch-track{background:rgba(217,255,98,.18);border-color:rgba(217,255,98,.35)}
435: .switch input:checked + .switch-track::after{transform:translateX(13px);background:var(--acid)}
436: .text-fields{transition:opacity .2s}
