463: /* Toast */
464: .toast{
465:   position:fixed;bottom:24px;left:50%;transform:translate(-50%,18px);z-index:120;
466:   min-width:180px;max-width:calc(100vw - 32px);display:flex;align-items:center;gap:9px;
467:   background:#e8e5dd;color:#151514;border-radius:100px;padding:10px 15px 10px 12px;
