Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -803,8 +803,341 @@
   <span id="toastMsg">Ready</span>
 </div>

 <script>
-/* App logic is added below. */
+(() => {
+  'use strict';
+  const $ = (selector, root = document) => root.querySelector(selector);
+  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
+  const canvas = $('#studioCanvas');
+  const ctx = canvas.getContext('2d');
+  const defaults = { brightness:100, contrast:100, saturation:100, hue:0, blur:0, invert:0, ratio:'1:1', fit:'crop', textOn:false, text:'', textStyle:'serif', textAlign:'center', textPos:'bottom', textSize:100 };
+  let items = [];
+  let activeId = null;
+  let state = {...defaults};
+  let seed = Math.floor(Math.random() * 900000) + 100000;
+  let seedLocked = false;
+  let busy = false;
+  let generationToken = 0;
+  let timerInterval = null;
+  let toastTimer = null;
+  const randomSeed = () => Math.floor(Math.random() * 2147483646) + 1;
+  const activeItem = () => items.find(item => item.id === activeId);
+
+  function toast(message, type = 'success') {
+    const el = $('#toast');
+    $('#toastMsg').textContent = message;
+    el.className = `toast show ${type}`;
+    clearTimeout(toastTimer);
+    toastTimer = setTimeout(() => el.classList.remove('show'), 2800);
+  }
+  function updateSeed() {
+    $('#seedValue').textContent = String(seed).padStart(6, '0');
+    $('#seedMeta').textContent = `SEED ${String(seed).padStart(6, '0')}`;
+  }
+  function updateMeta() {
+    const item = activeItem();
+    if (!item) return;
+    const size = `${canvas.width} × ${canvas.height}`;
+    $('#canvasMeta').textContent = size;
+    $('#sourceSize').textContent = `${item.image.naturalWidth || item.image.width} × ${item.image.naturalHeight || item.image.height}`;
+    $('#typeBadge').textContent = item.type === 'generated' ? 'GENERATED' : item.type === 'imported' ? 'IMPORTED' : 'STUDY';
+    $('#typeBadge').className = `type-badge ${item.type === 'generated' ? 'gen' : item.type === 'imported' ? 'import' : ''}`;
+    $('#currentCaption').textContent = item.title;
+    updateSeed();
+  }
+  function dimensionsForRatio(ratio, sourceW, sourceH) {
+    const maxSide = 1280;
+    const parts = ratio.split(':').map(Number);
+    const targetRatio = parts[0] / parts[1];
+    let w, h;
+    if (targetRatio >= 1) { w = maxSide; h = Math.round(maxSide / targetRatio); }
+    else { h = maxSide; w = Math.round(maxSide * targetRatio); }
+    if (!ratio || !sourceW || !sourceH) return [w, h];
+    return [w, h];
+  }
+  function drawBase(image) {
+    const sourceW = image.naturalWidth || image.width;
+    const sourceH = image.naturalHeight || image.height;
+    const [w, h] = dimensionsForRatio(state.ratio, sourceW, sourceH);
+    if (canvas.width !== w || canvas.height !== h) { canvas.width = w; canvas.height = h; }
+    ctx.save();
+    ctx.filter = 'none';
+    ctx.fillStyle = '#111114';
+    ctx.fillRect(0, 0, w, h);
+    let sx = 0, sy = 0, sw = sourceW, sh = sourceH, dx = 0, dy = 0, dw = w, dh = h;
+    if (state.fit === 'crop') {
+      const scale = Math.max(w / sourceW, h / sourceH);
+      sw = w / scale; sh = h / scale;
+      sx = (sourceW - sw) / 2; sy = (sourceH - sh) / 2;
+    } else {
+      const scale = Math.min(w / sourceW, h / sourceH);
+      dw = sourceW * scale; dh = sourceH * scale;
+      dx = (w - dw) / 2; dy = (h - dh) / 2;
+    }
+    ctx.filter = `brightness(${state.brightness}%) contrast(${state.contrast}%) saturate(${state.saturation}%) hue-rotate(${state.hue}deg) blur(${state.blur}px) invert(${state.invert}%)`;
+    ctx.drawImage(image, sx, sy, sw, sh, dx, dy, dw, dh);
+    ctx.restore();
+    if (state.textOn && state.text.trim()) drawText();
+    updateMeta();
+    updateGalleryThumb(activeId);
+  }
+  function drawText() {
+    const text = state.text.trim();
+    if (!text) return;
+    const w = canvas.width, h = canvas.height;
+    const family = state.textStyle === 'sans' ? '700' : state.textStyle === 'mono' ? '500' : '400';
+    const face = state.textStyle === 'sans' ? 'Manrope, sans-serif' : state.textStyle === 'mono' ? 'DM Mono, monospace' : 'Instrument Serif, Georgia, serif';
+    const size = Math.max(20, Math.round(Math.min(w, h) * .055 * state.textSize / 100));
+    ctx.save();
+    ctx.font = `${family} ${size}px ${face}`;
+    ctx.textAlign = state.textAlign;
+    ctx.textBaseline = state.textPos === 'top' ? 'top' : 'bottom';
+    const margin = Math.round(Math.min(w, h) * .065);
+    const x = state.textAlign === 'left' ? margin : state.textAlign === 'right' ? w - margin : w / 2;
+    const y = state.textPos === 'top' ? margin : h - margin;
+    ctx.shadowColor = 'rgba(0,0,0,.7)'; ctx.shadowBlur = size * .22; ctx.shadowOffsetY = 2;
+    ctx.lineWidth = Math.max(2, size * .09); ctx.strokeStyle = 'rgba(0,0,0,.48)';
+    ctx.fillStyle = '#fffdf5';
+    const maxWidth = w - margin * 2;
+    const words = text.split(/\s+/); const lines = []; let line = '';
+    for (const word of words) {
+      const test = line ? `${line} ${word}` : word;
+      if (line && ctx.measureText(test).width > maxWidth) { lines.push(line); line = word; } else line = test;
+    }
+    if (line) lines.push(line);
+    const lineHeight = size * 1.15;
+    if (state.textPos === 'top') {
+      lines.forEach((value, i) => { const yy = y + i * lineHeight; ctx.strokeText(value, x, yy, maxWidth); ctx.fillText(value, x, yy, maxWidth); });
+    } else {
+      lines.reverse().forEach((value, i) => { const yy = y - i * lineHeight; ctx.strokeText(value, x, yy, maxWidth); ctx.fillText(value, x, yy, maxWidth); });
+    }
+    ctx.restore();
+  }
+  function saveState() {
+    const item = activeItem();
+    if (item) item.state = {...state};
+  }
+  function syncControls() {
+    ['brightness','contrast','saturation','hue','blur','invert','textSize'].forEach(id => {
+      const input = $(`#${id}`); input.value = state[id]; input.classList.toggle('active', Number(input.value) !== defaults[id]);
+      input.style.setProperty('--pct', `${(Number(input.value) - Number(input.min)) / (Number(input.max) - Number(input.min)) * 100}%`);
+      const suffix = id === 'hue' ? '°' : id === 'blur' ? 'px' : '%';
+      $(`#${id}Out`).textContent = `${state[id]}${suffix}`;
+    });
+    $$('.ratio-btn').forEach(button => button.classList.toggle('active', button.dataset.ratio === state.ratio));
+    $$('#fitMode button').forEach(button => button.classList.toggle('active', button.dataset.fit === state.fit));
+    $('#textToggle').checked = state.textOn;
+    $('#textFields').classList.toggle('off', !state.textOn);
+    $('#overlayText').value = state.text;
+    $('#textStyle').value = state.textStyle;
+    $('#textAlign').value = state.textAlign;
+    $('#textSize').value = state.textSize;
+    $$('#textPos button').forEach(button => button.classList.toggle('active', button.dataset.pos === state.textPos));
+  }
+  function render() {
+    const item = activeItem();
+    if (item) drawBase(item.image);
+  }
+  function thumbData(item) {
+    const temp = document.createElement('canvas');
+    temp.width = 120; temp.height = 76;
+    const c = temp.getContext('2d');
+    const iw = item.image.naturalWidth || item.image.width, ih = item.image.naturalHeight || item.image.height;
+    const scale = Math.max(temp.width / iw, temp.height / ih);
+    const sw = temp.width / scale, sh = temp.height / scale;
+    c.drawImage(item.image, (iw-sw)/2, (ih-sh)/2, sw, sh, 0, 0, temp.width, temp.height);
+    return temp.toDataURL('image/jpeg', .72);
+  }
+  function updateGalleryThumb(id) {
+    const item = items.find(entry => entry.id === id);
+    const element = $(`.gallery-item[data-id="${id}"] .gallery-thumb`);
+    if (item && element) element.style.backgroundImage = `url("${thumbData(item)}")`;
+  }
+  function renderGallery() {
+    const gallery = $('#gallery');
+    gallery.innerHTML = '';
+    $('#galleryCount').textContent = `${items.length} ${items.length === 1 ? 'image' : 'images'}`;
+    if (!items.length) {
+      gallery.innerHTML = '<div class="gallery-empty">Your images will collect here</div>';
+      return;
+    }
+    items.forEach(item => {
+      const button = document.createElement('button');
+      button.type = 'button'; button.className = `gallery-item${item.id === activeId ? ' active' : ''}`; button.dataset.id = item.id;
+      button.setAttribute('aria-label', `Open ${item.title}`);
+      const thumb = document.createElement('span'); thumb.className = 'gallery-thumb';
+      thumb.style.backgroundImage = `url("${thumbData(item)}")`;
+      const kind = document.createElement('span'); kind.className = 'gallery-kind'; kind.textContent = item.type === 'generated' ? 'GEN' : item.type === 'imported' ? 'FILE' : 'STUDY';
+      thumb.append(kind);
+      const label = document.createElement('span'); label.className = 'gallery-label'; label.textContent = item.title;
+      const sub = document.createElement('span'); sub.className = 'gallery-sub'; sub.textContent = item.type === 'generated' ? `SEED ${item.seed}` : 'LOCAL IMAGE';
+      button.append(thumb, label, sub);
+      button.addEventListener('click', () => selectItem(item.id));
+      gallery.append(button);
+    });
+  }
+  function selectItem(id) {
+    if (id === activeId) return;
+    saveState(); activeId = id;
+    const item = activeItem();
+    state = {...defaults, ...(item.state || {})};
+    if (item.seed) seed = item.seed;
+    syncControls(); render(); renderGallery();
+  }
+  function addImage(image, type, title, imageSeed = null) {
+    const id = `${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
+    const item = {id, image, type, title: title || 'Untitled image', seed:imageSeed, state:{...defaults}};
+    saveState(); items.unshift(item); items = items.slice(0, 30); activeId = id; state = {...defaults};
+    if (imageSeed) seed = imageSeed;
+    syncControls(); render(); renderGallery();
+    return item;
+  }
+  function imageFromUrl(url) {
+    return new Promise((resolve, reject) => {
+      const image = new Image();
+      if (!url.startsWith('data:') && !url.startsWith('blob:')) image.crossOrigin = 'anonymous';
+      image.onload = () => resolve(image);
+      image.onerror = () => reject(new Error('Could not load this image. Check the URL and image-host permissions.'));
+      image.src = url;
+    });
+  }
+  function setBusy(value) {
+    busy = value;
+    $('#generateBtn').disabled = value;
+    $('#generateLabel').textContent = value ? 'Creating image…' : 'Generate image';
+    $('#loadingOverlay').classList.toggle('show', value);
+    $('#loadingOverlay').setAttribute('aria-hidden', String(!value));
+    if (value) {
+      const started = Date.now();
